; The Dragon Balls (frieza.js draw(): steal and eighth; ki-art.js 'dragon'
; from assets/sprites/dragon-balls.png, generated by snes/gen/frieza.mjs).
; The seven rise from the pouch to the altar in an opening ring (11 px
; each, one 16x16 OBJ); the eighth hangs over Goku (18 px, four OBJ).
; VRAM: core's FIELD_OBJ_A region (7 cells), claimed while a ball scene
; draws; the tiles go up in Frieza's vblank (fz_balls_nmi) before any
; sprite points at them. Palette: the second free OBJ palette.

!FZB_CELL0 = $0122                    ; FIELD_OBJ_A: cell k at $122 + 2k
!FZB_VRAM_TOP = $7220
!FZB_VRAM_BOT = $7320

; The ball scenes on their map: claim the region, ask for the set, draw.
; Called from fz_draw_scene (steal, before Frieza: the browser draws the
; Balls over him) and from the effects branch (eighth).
fz_balls_steal:
	LDA !fz_sflags
	AND.w #!FZSF_ALTAR
	BEQ +
	LDA !fz_sage                      ; at the altar they are gone by 64
	CMP.w #64
	BCC +
	RTS
+	LDA.l !fzp_mask
	AND.w #$007F
	BNE +
	RTS
+	LDA.w #1
	JSR fz_balls_want
	BCC +
	RTS
+	JSR fz_camera
	; tx, ty: to the altar (228 - 8, 132 - 10) from Goku at the cue, else (40, -42)
	LDA !fz_sflags
	AND.w #!FZSF_ALTAR
	BEQ .free
	LDA.w #220
	SEC
	SBC !fz_sx
	STA !fz_t4                        ; tx
	LDA.w #122
	SEC
	SBC !fz_sy
	STA !fz_t5                        ; ty
	BRA +
.free
	LDA.w #40
	STA !fz_t4
	LDA.w #-42
	STA !fz_t5
+	; t = min(1, age / 60): the straight part in 8.8, the same for every ball
	LDA !fz_sage
	CMP.w #60
	BCC +
	LDA.w #60
+	STA !fz_t6
	LDA !fz_t4
	JSR fz_scale60                    ; tx * t: whole part, fraction
	STA !fz_t4
	LDA !fz_m4
	STA !fz_t0
	LDA !fz_t5
	JSR fz_scale60
	STA !fz_t5
	LDA !fz_m4
	STA !fz_t1
	; the balls Frieza holds
	LDA !fz_sage
	CMP.w #64
	BCC +
	LDA.w #63
+	ASL
	STA !fz_t6                        ; age word index into the ring tables
	LDX.w #0
.ball
	STX !fz_t7
	LDA.l !fzp_mask
	AND.l fz_bit_table,X              ; (bit i: words 1, 2, 4, ...)
	BEQ .next
	; x = round(sx - camX + tx t + ox)
	TXA
	ASL
	ASL
	ASL
	ASL
	ASL
	ASL                               ; i * 128 (64 ages x 2 bytes)
	CLC
	ADC !fz_t6
	TAX
	LDA.l frieza_steal_ox,X
	CLC
	ADC !fz_t0                        ; the fractions, then half a pixel
	CLC
	ADC.w #$0080
	JSR fz_asr8
	CLC
	ADC !fz_t4                        ; the whole pixels
	CLC
	ADC !fz_sx
	SEC
	SBC !fz_cam_x
	SEC
	SBC.w #!FRIEZA_BALL_W/2           ; the left edge
	STA.w !core_spr_x&$FFFF
	LDA.l frieza_steal_oy,X
	CLC
	ADC !fz_t1
	CLC
	ADC.w #$0080
	JSR fz_asr8
	CLC
	ADC !fz_t5
	CLC
	ADC !fz_sy
	SEC
	SBC.w #12
	SEC
	SBC !fz_cam_y
	SEC
	SBC.w #!FRIEZA_BALL_H/2           ; the top edge
	STA.w !core_spr_y&$FFFF
	LDA !fz_t7
	LSR                               ; ball i (X held i * 2)
	ASL                               ; cell i: tile $122 + 2i
	CLC
	ADC.w #!FZB_CELL0
	JSR fz_balls_put
.next
	LDX !fz_t7
	INX
	INX
	CPX.w #7*2
	BCC .ball
.out
	RTS

; eighth: the eighth Ball over Goku (the exterior follower's spot on the
; deck, else Goku at the cue), y - 36.
fz_balls_eighth:
	LDA.w #2
	JSR fz_balls_want
	BCC +
	RTS
+	JSR fz_camera
	LDA $DC
	CMP.w #195
	BNE .here
	; exteriorFollowerPose at rest: (128 - 16, 112 + 60)
	LDA.w #112
	STA !fz_t4
	LDA.w #172
	STA !fz_t5
	BRA +
.here
	LDA !fz_sx
	SEC
	SBC !fz_cam_x
	STA !fz_t4
	LDA !fz_sy
	SEC
	SBC !fz_cam_y
	STA !fz_t5
+	LDA !fz_t5
	SEC
	SBC.w #36+(!FRIEZA_BALL8_H/2)
	STA !fz_t5
	LDA !fz_t4
	SEC
	SBC.w #!FRIEZA_BALL8_W/2
	STA !fz_t4
	; four cells: (0,0) (16,0) (0,16) (16,16)
	LDX.w #0
-	STX !fz_t7
	LDA.l fz_ball8_dx,X
	CLC
	ADC !fz_t4
	STA.w !core_spr_x&$FFFF
	LDA.l fz_ball8_dy,X
	CLC
	ADC !fz_t5
	STA.w !core_spr_y&$FFFF
	TXA
	CLC
	ADC.w #!FZB_CELL0
	JSR fz_balls_put
	LDX !fz_t7
	INX
	INX
	CPX.w #4*2
	BCC -
	RTS
fz_ball8_dx:
	dw 0, 16, 0, 16
fz_ball8_dy:
	dw 0, 0, 16, 16

; One 16x16 ball cell: A16 = tile, !core_spr_x/_y set.
fz_balls_put:
	STA !fz_t3
	JSR fz_spr_palette2
	LDA !fz_spr_pal2
	AND.w #$0007
	XBA
	ASL
	ORA.w #$3000                      ; priority 3
	ORA !fz_t3
	STA.w !core_spr_tile&$FFFF
	STZ.w !core_spr_size&$FFFF
	JSL core_oam_add_front
	BCC +
	JSL core_oam_add
+	RTS

; A16 = set (1 seven, 2 eighth): this frame draws it. C set while it cannot
; show yet (the region is someone else's, or the tiles are not up).
fz_balls_want:
	STA !fz_t3
	LDA.w #!VRAM_FIELD_OBJ_A
	LDX.w #!FZ_VRAM_OWNER
	JSL core_vram_claim
	BCS .no
	SEP #$20
	LDA !fz_t3
	STA.l !fzb_req
	LDA.b #1
	STA.l !fzb_claim
	LDA !fz_t3
	STA.l !fzb_palsrc                 ; the second palette holds the Balls
	CMP.l !fzb_have
	REP #$20
	BNE .no                           ; uploaded in this vblank, drawn next frame
	CLC
	RTS
.no
	SEC
	RTS

; Every busy frame (after the draws): give the region back once no ball
; scene drew this frame.
fz_balls_tick:
	LDA.l !fzb_claim
	AND.w #$00FF
	BEQ .out
	LDA.l !fzb_req
	AND.w #$00FF
	BNE .out
	SEP #$20
	LDA.b #0
	STA.l !fzb_claim
	STA.l !fzb_have
	STA.l !fzb_palsrc
	REP #$20
	LDA.w #!VRAM_FIELD_OBJ_A
	LDX.w #!FZ_VRAM_OWNER
	JSL core_vram_release
.out
	RTS

; Vblank (DB = $80): the requested set into the region (two DMAs).
fz_balls_nmi:
	LDA.l !fzb_req
	AND.w #$00FF
	BEQ .out
	CMP.l !fzb_have
	BNE +
.out
	RTS
+	; up to 896 bytes: about 6 scanlines with a margin
	JSL core_vblank_lines
	CMP.w #8
	BCC .out
	LDA.l !fzb_req
	AND.w #$00FF
	CMP.w #2
	BEQ .eight
	LDA.w #frieza_balls_top
	STA.l $7E0000|!fz_t0
	LDA.w #frieza_balls_bottom
	STA.l $7E0000|!fz_t1
	LDA.w #7*64
	BRA .dma
.eight
	LDA.w #frieza_ball8_top
	STA.l $7E0000|!fz_t0
	LDA.w #frieza_ball8_bottom
	STA.l $7E0000|!fz_t1
	LDA.w #4*64
.dma
	STA.l $7E0000|!fz_t2
	SEP #$20
	LDA.b #$80
	STA $2115
	LDA.b #$01
	STA $4370
	LDA.b #$18
	STA $4371
	LDA.b #frieza_balls_top>>16
	STA $4374
	REP #$20
	LDA.w #!FZB_VRAM_TOP
	STA $2116
	LDA.l $7E0000|!fz_t0
	STA $4372
	LDA.l $7E0000|!fz_t2
	STA $4375
	SEP #$20
	LDA.b #$80
	STA $420B
	REP #$20
	LDA.w #!FZB_VRAM_BOT
	STA $2116
	LDA.l $7E0000|!fz_t1
	STA $4372
	LDA.l $7E0000|!fz_t2
	STA $4375
	SEP #$20
	LDA.b #$80
	STA $420B
	LDA.l !fzb_req
	STA.l !fzb_have
	REP #$20
	RTS

; A16 = signed d, !fz_t6 = n (0-60) -> d * n / 60 as A16 = signed whole
; pixels and !fz_m4 = signed fraction in 1/256 (both carry the sign of d;
; the fraction is truncated, below 1/256 px).
fz_scale60:
	STA !fz_m6
	JSR fz_abs
	STA !fz_m0
	LDA !fz_t6
	STA !fz_m1
	JSR fz_mul16                      ; |d| * n (< 65536)
	LDA !fz_m2
	LDX.w #60
	JSR fz_divmod                     ; A16 = remainder, !fz_m5 = quotient
	PHA
	LDA !fz_m5
	STA !fz_m7                        ; whole
	PLA
	XBA
	AND.w #$FF00                      ; remainder * 256 (< 15360)
	LDX.w #60
	JSR fz_divmod
	LDA !fz_m5
	STA !fz_m4                        ; fraction (0-255)
	LDA !fz_m6
	BPL +
	LDA !fz_m4
	EOR.w #$FFFF
	INC
	STA !fz_m4
	LDA !fz_m7
	EOR.w #$FFFF
	INC
	RTS
+	LDA !fz_m7
	RTS

; A16 >> 8, arithmetic (floor).
fz_asr8:
	XBA
	AND.w #$00FF
	CMP.w #$0080
	BCC +
	ORA.w #$FF00
+	RTS

